(()=>{'use strict';const login=document.getElementById('login'),hq=document.getElementById('hq');document.getElementById('signin').onclick=()=>{login.classList.add('hidden');hq.classList.remove('hidden');sessionStorage.setItem('vc-hq-preview','1')};document.getElementById('logout').onclick=()=>{sessionStorage.removeItem('vc-hq-preview');hq.classList.add('hidden');login.classList.remove('hidden')};if(sessionStorage.getItem('vc-hq-preview')==='1'){login.classList.add('hidden');hq.classList.remove('hidden')}document.querySelectorAll('.tab').forEach(t=>t.onclick=()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));t.classList.add('active')});const boxes=['destLocal','destGoogle','destIcloud'].map(id=>document.getElementById(id)).filter(Boolean),mode=document.getElementById('backupMode');function backupMode(){if(!mode)return;const names=boxes.filter(x=>x.checked).map(x=>x.id==='destLocal'?'Local / NAS':x.id==='destGoogle'?'Google Drive':'iCloud');mode.textContent='Mode: '+(names.length?names.join(' + '):'No backup destination selected');mode.className=names.length?'ok':''}boxes.forEach(x=>x.onchange=backupMode);const save=document.getElementById('saveDest');if(save)save.onclick=()=>{backupMode();save.textContent='Saved';setTimeout(()=>save.textContent='Save Selection',1200)};backupMode();})();